    def get_history_for_llm(self, max_msgs=20, session_id=None):
        """构造 LLM 历史消息列表，可按 session_id 过滤。"""
        records = self.get_recent_conversations(max_msgs * 2, session_id=session_id)
        msgs = []
        prev_role = None
        prev_content = None
        for rec in records[-max_msgs * 2:]:
            role = 'user' if rec.get('direction') == 'in' else 'assistant'
            content = rec.get('text')
            if content:
                # 去重：跳过与上一条相同 role + content 的连续重复记录
                if role == prev_role and content == prev_content:
                    continue
                msgs.append({'role': role, 'content': content})
                prev_role = role
                prev_content = content
        return msgs[-max_msgs:]

