    def list_recent_tasks(self, hours=48, limit=100,
                          kind=None, status=None, project_id=None):
        """获取最近 N 小时内的任务列表（支持过滤）。"""
        from datetime import datetime, timedelta
        cutoff = (datetime.now() - timedelta(hours=hours)).isoformat()
        query = (
            'SELECT t.*, p.title as project_title '
            'FROM tasks t LEFT JOIN projects p ON t.project_id = p.id '
            'WHERE t.created_at >= ?'
        )
        params = [cutoff]
        if kind:
            query += ' AND t.kind=?'
            params.append(kind)
        if status:
            query += ' AND t.status=?'
            params.append(status)
        if project_id:
            query += ' AND t.project_id=?'
            params.append(project_id)
        query += ' ORDER BY t.priority ASC, t.created_at DESC LIMIT ?'
        params.append(limit)
        with self._cursor() as cur:
            cur.execute(query, params)
            rows = cur.fetchall()
        return [dict(r) for r in rows]

    def list_tasks_paginated(self, status=None, kind=None, project_id=None,
                             search=None, created_after=None, created_before=None,
                             limit=10, offset=0):
        """分页任务列表（支持多条件过滤）。"""
        query = (
            'SELECT t.*, p.title as project_title '
            'FROM tasks t LEFT JOIN projects p ON t.project_id = p.id'
        )
        where_parts = []
